def check_n(n):
    if n > 2000:
        return "n > 2000"
    if n % 13 != 0:
        return "n not divisible by 13"
    if n % 3 != 0:
        return "n not divisible by 3 (required by row/col constraint)"

    max_multiple_39 = (2000 // 39) * 39
    if n != max_multiple_39:
        return f"Not the largest multiple of 39 below 2000. Largest is {max_multiple_39}"
    return "All arithmetic constraints met"

print(f"Testing n=1989: {check_n(1989)}")
print(f"Largest multiple of 39 <= 2000 is: {(2000 // 39) * 39}")
